mapper.select:
SELECT , (SELECT COUNT(*) FROM LECTURE_PROGRESS P WHERE P.LECTURE_ID = L.LECTURE_ID) AS LEARNER_CNT, (SELECT COUNT(*) FROM LECTURE_PROGRESS P WHERE P.LECTURE_ID = L.LECTURE_ID AND P.COMPLETED_YN = 'Y') AS COMPLETED_CNT FROM LECTURE L LEFT JOIN SURVEY S ON S.SURVEY_ID = L.SURVEY_ID
AND L.STATUS = #{status}
AND L.USE_YN = #{useYn}
AND (L.TITLE LIKE '%' || #{searchKeyword} || '%' OR L.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')
ORDER BY L.REGIST_DT DESC, L.LECTURE_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM LECTURE L


		AND L.STATUS = #{status}


		AND L.USE_YN = #{useYn}


		AND (L.TITLE LIKE '%' || #{searchKeyword} || '%'
			OR L.DESCRIPTION LIKE '%' || #{searchKeyword} || '%')

SELECT L.LECTURE_ID, L.TITLE, L.DURATION_SEC, L.COMPLETE_RATE, L.SURVEY_ID, S.TITLE AS SURVEY_TITLE, P.USER_ID, U.USER_NM, P.WATCHED_SEC, CASE WHEN L.DURATION_SEC > 0 AND P.WATCHED_SEC * 100 >= L.DURATION_SEC * L.COMPLETE_RATE THEN 'Y' ELSE 'N' END AS VIDEO_COMPLETED_YN, CASE WHEN L.SURVEY_ID IS NULL OR S.SURVEY_ID IS NULL THEN 'N' WHEN EXISTS ( SELECT 1 FROM SURVEY_PARTICIPATION SP WHERE SP.SURVEY_ID = L.SURVEY_ID AND SP.USER_ID = P.USER_ID ) THEN 'Y' ELSE 'N' END AS SURVEY_PARTICIPATED_YN, CASE WHEN L.DURATION_SEC > 0 AND P.WATCHED_SEC * 100 >= L.DURATION_SEC * L.COMPLETE_RATE AND ( L.SURVEY_ID IS NULL OR S.SURVEY_ID IS NULL OR EXISTS ( SELECT 1 FROM SURVEY_PARTICIPATION SP WHERE SP.SURVEY_ID = L.SURVEY_ID AND SP.USER_ID = P.USER_ID ) ) THEN 'Y' ELSE 'N' END AS COMPLETED_YN, P.COMPLETED_DT, P.UPDT_DT FROM LECTURE_PROGRESS P JOIN LECTURE L ON L.LECTURE_ID = P.LECTURE_ID LEFT JOIN SURVEY S ON S.SURVEY_ID = L.SURVEY_ID LEFT JOIN APP_USER U ON U.USER_ID = P.USER_ID
AND L.LECTURE_ID = #{lectureId}
AND (P.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%' OR L.TITLE LIKE '%' || #{searchKeyword} || '%')
ORDER BY L.TITLE, U.USER_NM, P.USER_ID LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) FROM LECTURE_PROGRESS P JOIN LECTURE L ON L.LECTURE_ID = P.LECTURE_ID LEFT JOIN APP_USER U ON U.USER_ID = P.USER_ID
AND L.LECTURE_ID = #{lectureId}
AND (P.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%' OR L.TITLE LIKE '%' || #{searchKeyword} || '%')
